import { Node, mergeAttributes } from '@tiptap/core';

export const MathType = Node.create({
  name: 'mathtype',

  group: 'inline',

  inline: true,

  atom: true,

  draggable: true,

  parseHTML() {
    return [
      {
        tag: 'img',
        getAttrs(node) {
          // Only accept <img> elements generated by MathType.
          return (node as HTMLElement).classList.contains('Wirisformula') ? {} : false;
        },
        priority: 100,
      },
    ];
  },
  renderHTML({ HTMLAttributes }) {
    return ['span', { class: 'ex-mathype' }, ['img', mergeAttributes(HTMLAttributes)]];
  },
  addAttributes() {
    return {
      class: {
        default: 'Wirisformula',
      },
      style: {
        default: '',
        parseHTML(element) {
          return element.getAttribute('style');
        },
      },
      width: {
        default: '',
        parseHTML(element) {
          return element.getAttribute('width');
        },
      },
      height: {
        default: '',
        parseHTML(element) {
          return element.getAttribute('height');
        },
      },
      'data-mathml': {
        default: '',
        parseHTML(element) {
          return element.getAttribute('data-mathml');
        },
      },
      'data-custom-editor': {
        default: null,
        parseHTML(element) {
          return element.getAttribute('data-custom-editor');
        },
      },
      src: {
        default: null,
      },
    };
  },
  addNodeView() {
    const syncImage = (img: HTMLImageElement, attrs: Record<string, any>) => {
      Array.from(img.attributes).forEach((attr) => {
        if (attrs[attr.name] == null) img.removeAttribute(attr.name);
      });
      Object.keys(attrs).forEach((key) => {
        if (attrs[key] == null) return;
        img.setAttribute(key, attrs[key]);
      });
    };

    return ({ node }) => {
      const dom = document.createElement('span');
      dom.className = 'ex-mathype tiptap-widget';
      const img = document.createElement('img');
      syncImage(img, node.attrs);
      dom.appendChild(img);
      return {
        dom,
        update(updatedNode) {
          if (updatedNode.type !== node.type) return false;
          syncImage(img, updatedNode.attrs);
          return true;
        },
        selectNode() {
          dom.classList.add('ex-selected');
        },
        deselectNode() {
          dom.classList.remove('ex-selected');
        },
      };
    };
  },
});
